  lines.push(line);

  if (lines.length === 3) {
    let n = parseInt(lines[0]);
    let capacities = lines[1].split(" ").slice(0, n).map(Number);
    let minCap = parseInt(lines[2]);

    console.log(getResult(n, capacities, minCap));

    lines.length = 0;
  }
});

